function manifest(spec, category) {
  return {
    schemaVersion: 1, id: `ipollowork.${category === "slides" ? "pptx" : "site"}-${spec.slug}`, version: "1.0.0", kind: "design",
    category, subcategory: spec.subcategory, style: spec.style, tags: [spec.subcategory, spec.style, category === "slides" ? "pptx-compatible" : "responsive", "themeable"],
    ...(category === "slides" ? { pptxCompatibility: "native-editable" } : {}), surface: "design", title: spec.title, description: spec.desc,
    cover: "cover.png", entry: "entry.html", source: { name: "iPolloWork", license: "MIT" },
    designSystem: { tokenVersion: 1, editableGroups: ["theme", "background", "typography", "components"], tokens: "design-tokens.css", variables: tokenVariables },
    applyChecklist: category === "slides" ? [
      "Replace every sample claim and metric with verified brief content.", "Preserve the six-slide narrative, template-specific composition, and object geometry.",
      "Preserve every data-pptx-text and data-pptx-shape marker so exported objects remain editable.", "Apply brand styling only through design tokens without replacing the DOM skeleton.",
      "Check text bounds, contrast, source labels, and slide order before exporting.",
    ] : [
      "Replace all sample content with the complete project brief while preserving this template's information architecture.", "Preserve responsive navigation, semantic landmarks, anchored sections, and visible action feedback.",
      "Apply brand styling through declared design tokens without changing layout geometry or media dimensions.", "Keep the primary visual and calls to action specific to the represented service.",
      "Verify mobile layout, links, focus states, form labels, and text overflow before publishing.",
    ], minimumAppVersion: "0.17.28",
  };
}

function tokenCss(spec) {
  const [bg, surface, text, muted, border, primary, secondary, accent] = palettes[spec.palette];
  return `/* ipw-theme:start */\n/* ipw-design-system: ${spec.slug} */\n:root {\n  --ipw-color-bg: ${bg};\n  --ipw-color-surface: ${surface};\n  --ipw-color-text: ${text};\n  --ipw-color-muted: ${muted};\n  --ipw-color-border: ${border};\n  --ipw-color-primary: ${primary};\n  --ipw-color-secondary: ${secondary};\n  --ipw-color-accent: ${accent};\n  --ipw-color-success: #20815f;\n  --ipw-color-warning: #bd7a24;\n  --ipw-color-danger: #c54e54;\n  --ipw-color-on-primary: #ffffff;\n  --ipw-font-display: Georgia, "Times New Roman", serif;\n  --ipw-font-body: Arial, Helvetica, sans-serif;\n  --ipw-type-scale: 1;\n  --ipw-body-line-height: 1.55;\n  --ipw-content-width: 1180px;\n  --ipw-page-padding: 32px;\n  --ipw-section-space: 88px;\n  --ipw-button-radius: 8px;\n  --ipw-card-bg: ${surface};\n  --ipw-card-border: ${border};\n  --ipw-card-radius: 8px;\n  --ipw-card-shadow: 0 18px 46px rgb(15 23 42 / 12%);\n}\n/* ipw-theme:end */\n`;
}

