function siteHtml(spec) {
  const content = siteContent[spec.layout];
  const cards = spec.sections.map((s,i)=>`<article class="story-card"><span>0${i+1}</span><h3>${s}</h3><p>${content.cards[i]}</p><a href="#contact">Explore <span aria-hidden="true">↗</span></a></article>`).join("");
  return `<!doctype html><html lang="en" data-ipw-mobile-ready="true"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${spec.title}</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--ipw-color-bg);color:var(--ipw-color-text);font-family:var(--ipw-font-body);line-height:var(--ipw-body-line-height)}a{color:inherit;text-decoration:none}button,input{font:inherit}.shell{width:min(var(--ipw-content-width),calc(100% - 2 * var(--ipw-page-padding)));margin:auto}.site-nav{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--ipw-color-border)}.brand{font:600 20px var(--ipw-font-display)}.nav-links{display:flex;gap:28px;align-items:center}.nav-links a{font-size:12px}.button{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:0 18px;border:0;border-radius:var(--ipw-button-radius);background:var(--ipw-color-primary);color:var(--ipw-color-on-primary);font-weight:700;cursor:pointer}.button.alt{background:var(--ipw-color-secondary);color:var(--ipw-color-text)}.mobile-nav-toggle{display:none;width:42px;height:42px;border:1px solid var(--ipw-color-border);background:var(--ipw-color-surface);color:var(--ipw-color-text);font-size:20px}.hero{min-height:620px;display:grid;gap:54px;align-items:center;padding:68px 0}.hero-copy .eyebrow{color:var(--ipw-color-accent);font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:1px}.hero h1{max-width:720px;margin:18px 0 24px;font:500 calc(64px * var(--ipw-type-scale))/.96 var(--ipw-font-display)}.hero p{max-width:560px;color:var(--ipw-color-muted);font-size:17px}.hero-actions{display:flex;gap:10px;margin-top:28px}.hero-visual{position:relative;height:430px;overflow:hidden;background:var(--ipw-color-secondary);box-shadow:var(--ipw-card-shadow)}.hero-media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.16;mix-blend-mode:multiply}.index-strip{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--ipw-color-border);border-left:1px solid var(--ipw-color-border)}.index-strip>div{padding:20px;border-right:1px solid var(--ipw-color-border);border-bottom:1px solid var(--ipw-color-border)}.index-strip small{display:block;color:var(--ipw-color-muted);font-size:9px;text-transform:uppercase}.index-strip strong{display:block;margin-top:20px;font:500 23px var(--ipw-font-display)}.stories{padding:var(--ipw-section-space) 0}.section-head{display:grid;grid-template-columns:.38fr 1fr;gap:42px;margin-bottom:34px}.section-head span{color:var(--ipw-color-accent);font-size:10px;font-weight:900;text-transform:uppercase}.section-head h2{max-width:720px;margin:0;font:500 calc(44px * var(--ipw-type-scale))/1 var(--ipw-font-display)}.story-grid{display:grid;grid-template-columns:1.15fr .85fr .85fr;gap:13px}.story-card{min-height:330px;display:flex;flex-direction:column;padding:24px;border:1px solid var(--ipw-card-border);border-radius:var(--ipw-card-radius);background:var(--ipw-card-bg);box-shadow:var(--ipw-card-shadow)}.story-card:nth-child(2){margin-top:45px;background:var(--ipw-color-secondary)}.story-card:nth-child(3){margin-top:90px}.story-card>span{color:var(--ipw-color-accent);font-size:11px;font-weight:900}.story-card h3{margin:auto 0 12px;font:500 26px/1.06 var(--ipw-font-display)}.story-card p{margin:0;color:var(--ipw-color-muted);font-size:13px}.story-card a{margin-top:22px;font-weight:800}.contact-band{display:grid;grid-template-columns:1fr .8fr;gap:60px;align-items:end;padding:64px;background:var(--ipw-color-primary);color:var(--ipw-color-on-primary)}.contact-band h2{margin:0;font:500 48px/1 var(--ipw-font-display)}.contact-form{display:flex;gap:8px}.contact-form input{min-width:0;flex:1;height:44px;padding:0 14px;border:1px solid color-mix(in srgb,var(--ipw-color-on-primary) 35%,transparent);background:transparent;color:var(--ipw-color-on-primary)}.contact-form input::placeholder{color:color-mix(in srgb,var(--ipw-color-on-primary) 70%,transparent)}.contact-form .button{background:var(--ipw-color-accent)}[data-ipw-action-status]{min-height:20px;margin:10px 0 0;font-size:12px}.footer{display:flex;justify-content:space-between;padding:30px 0;color:var(--ipw-color-muted);font-size:11px}${siteLayoutCss[spec.layout]}${siteInteriorCss[spec.layout]}@media(max-width:760px){.shell{width:min(100% - 32px,var(--ipw-content-width))}.mobile-nav-toggle{display:grid;place-items:center}.nav-links{display:none;position:absolute;z-index:10;left:16px;right:16px;top:72px;padding:18px;background:var(--ipw-color-surface);border:1px solid var(--ipw-color-border);box-shadow:var(--ipw-card-shadow)}.nav-links.open{display:grid}.hero{min-height:auto;grid-template-columns:1fr;padding:48px 0}.hero h1{font-size:44px}.hero-visual{height:320px}.index-strip,.story-grid,.contact-band,.section-head{grid-template-columns:1fr}.stories{display:block}.story-card{display:flex;min-height:260px}.story-card:nth-child(2),.story-card:nth-child(3){margin-top:0;transform:none}.contact-band{padding:34px 24px;text-align:left}.contact-form{flex-direction:column}.footer{gap:20px;flex-direction:column}}
</style><link rel="stylesheet" href="design-tokens.css" data-ipw-design-tokens></head><body><main class="${spec.signature}" data-ipw-template="site-${spec.slug}"><div class="shell"><header class="site-nav"><a class="brand" href="#top">${spec.brand}</a><button class="mobile-nav-toggle" type="button" aria-expanded="false" aria-controls="site-menu" aria-label="Toggle navigation">☰</button><nav class="nav-links" id="site-menu">${spec.nav.map((n,i)=>`<a href="#${i===0?'stories':i===1?'about':'contact'}">${n}</a>`).join("")}<a class="button" href="#contact">${spec.cta}</a></nav></header><section class="hero" id="top"><div class="hero-copy"><span class="eyebrow">${spec.eyebrow}</span><h1>${spec.headline}</h1><p>${spec.note}</p><div class="hero-actions"><a class="button" href="#contact">${spec.cta}</a><a class="button alt" href="#stories">Explore</a></div></div><div class="hero-visual"><img class="hero-media" src="assets/visual.png" alt="${spec.title} visual"></div></section><div class="index-strip" id="about">${content.stats.map(([label,value])=>`<div><small>${label}</small><strong>${value}</strong></div>`).join("")}</div><section class="stories" id="stories"><div class="section-head"><span>Inside ${spec.brand}</span><h2>${spec.sections[0]}</h2></div><div class="story-grid">${cards}</div></section><section class="contact-band" id="contact"><div><span>${spec.cta}</span><h2>${content.contact}</h2></div><div><form class="contact-form"><label hidden for="contact-entry">Your email or reference</label><input id="contact-entry" required placeholder="Email or reference"><button class="button" type="submit">Continue</button></form><p role="status" aria-live="polite" data-ipw-action-status></p></div></section><footer class="footer"><span>© 2026 ${spec.brand}</span><span>Privacy · Accessibility · Contact</span></footer></div></main><script>(()=>{const toggle=document.querySelector('.mobile-nav-toggle');const menu=document.querySelector('#site-menu');toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));menu?.classList.toggle('open',open)});const form=document.querySelector('.contact-form');const status=document.querySelector('[data-ipw-action-status]');form?.addEventListener('submit',event=>{event.preventDefault();if(!form.checkValidity()){form.reportValidity();return}status.textContent='Demo request noted. Connect this form to your service before publishing.'});})();</script></body></html>`;
}

async function visualAsset(spec) {
  const [, surface, text, , border, primary, secondary, accent] = palettes[spec.palette];
  const svg = `<svg width="1200" height="800" xmlns="http://www.w3.org/2000/svg"><rect width="1200" height="800" fill="${surface}"/><rect x="70" y="70" width="1060" height="660" rx="12" fill="${secondary}"/><circle cx="875" cy="270" r="180" fill="${primary}"/><rect x="145" y="155" width="470" height="36" fill="${text}"/><rect x="145" y="215" width="330" height="18" fill="${border}"/><path d="M120 610 C 330 410, 540 720, 1090 470" fill="none" stroke="${accent}" stroke-width="42"/><text x="150" y="560" font-family="Arial" font-size="32" font-weight="700" fill="${text}">${spec.title.toUpperCase()}</text></svg>`;
  return sharp(Buffer.from(svg)).png().toBuffer();
}

async function writeTemplate(spec, category) {
  const directory = new URL(`ipollowork.${category === "slides" ? "pptx" : "site"}-${spec.slug}/`, root);
  await rm(directory, { recursive: true, force: true });
  await mkdir(new URL("assets/", directory), { recursive: true });
  await writeFile(new URL("manifest.json", directory), `${JSON.stringify(manifest(spec, category), null, 2)}\n`);
  await writeFile(new URL("design-tokens.css", directory), tokenCss(spec));
  await writeFile(new URL("entry.html", directory), category === "slides" ? slideHtml(spec) : siteHtml(spec));
  await writeFile(new URL("assets/visual.png", directory), await visualAsset(spec));
  // A real rendered cover replaces this deterministic placeholder in generate-template-covers.mjs.
  await writeFile(new URL("cover.png", directory), await sharp(await visualAsset(spec)).resize(960, 540, { fit: "cover" }).png().toBuffer());
}

for (const spec of slideSpecs) await writeTemplate(spec, "slides");
for (const spec of siteSpecs) await writeTemplate(spec, "site");
console.log(`Generated ${slideSpecs.length} slide templates and ${siteSpecs.length} website templates.`);
